export type SeriesControl = keyof typeof SERIES_CONTROLS;
const sprites = new Map(data.sprites.map((s) => [s.id, s as SpriteInfo]));
const source: ClipSource = {
  spriteInfo: (id) => sprites.get(id),
  displayList: (id, age) => {
